"""
Port interfaces (abstract base classes) for all infrastructure adapters.

Every concrete adapter — aws or onprem — implements the same port interface.
Business logic depends only on these ports; it never imports a concrete adapter.
"""

from __future__ import annotations

import abc
from typing import Any, Optional


class ObjectStoragePort(abc.ABC):
    """Port for object/blob storage (S3, MinIO, etc.)."""

    @abc.abstractmethod
    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[dict[str, str]] = None) -> None:
        """Store an object. Creates the bucket transparently if the adapter supports it."""

    @abc.abstractmethod
    def get_object(self, bucket: str, key: str) -> bytes:
        """Retrieve an object's bytes. Raises KeyError if not found."""

    @abc.abstractmethod
    def delete_object(self, bucket: str, key: str) -> None:
        """Delete an object. No-op if already absent."""

    @abc.abstractmethod
    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        """Return keys matching the prefix."""


class QueuePort(abc.ABC):
    """Port for message queue (SQS, RabbitMQ, Redis list, etc.)."""

    @abc.abstractmethod
    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        """Send a message. Returns a message id."""

    @abc.abstractmethod
    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        """Receive messages. Each dict has at least 'message_id', 'body', 'receipt_handle'."""

    @abc.abstractmethod
    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        """Acknowledge / delete a message."""


class EventingPort(abc.ABC):
    """Port for pub/sub eventing (SNS, NATS, Redis pub/sub, etc.)."""

    @abc.abstractmethod
    def publish(self, topic: str, message: str, attributes: Optional[dict[str, str]] = None) -> str:
        """Publish an event. Returns a message/event id."""

    @abc.abstractmethod
    def subscribe(self, topic: str, callback_url_or_id: str) -> str:
        """Register a subscription. Returns subscription id/arn."""


class SecretsPort(abc.ABC):
    """Port for secrets management (Secrets Manager, Vault, env-file, etc.)."""

    @abc.abstractmethod
    def get_secret(self, secret_id: str) -> str:
        """Retrieve a secret value. Raises KeyError if not found."""

    @abc.abstractmethod
    def put_secret(self, secret_id: str, value: str) -> None:
        """Create or update a secret."""


class LogSinkPort(abc.ABC):
    """Port for structured log sink (CloudWatch, file, stdout JSON, etc.)."""

    @abc.abstractmethod
    def emit(self, log_group: str, log_stream: str, message: str) -> None:
        """Emit a log entry."""

"""AWS (S3) object storage adapter."""

from __future__ import annotations

from typing import Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import ObjectStoragePort


class S3ObjectStorage(ObjectStoragePort):
    """ObjectStoragePort backed by AWS S3 (or LocalStack-compatible endpoint)."""

    def __init__(self, endpoint_url: Optional[str] = None, region_name: str = "us-east-1") -> None:
        kwargs: dict = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("s3", **kwargs)

    # -- helpers ---------------------------------------------------------------

    def _ensure_bucket(self, bucket: str) -> None:
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            self._client.create_bucket(Bucket=bucket)

    # -- port implementation ---------------------------------------------------

    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[dict[str, str]] = None) -> None:
        self._ensure_bucket(bucket)
        params: dict = {"Bucket": bucket, "Key": key, "Body": data}
        if metadata:
            params["Metadata"] = metadata
        self._client.put_object(**params)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(Bucket=bucket, Key=key)
            return resp["Body"].read()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in ("NoSuchKey", "404"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.delete_object(Bucket=bucket, Key=key)

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        try:
            resp = self._client.list_objects_v2(Bucket=bucket, Prefix=prefix)
            return [obj["Key"] for obj in resp.get("Contents", [])]
        except ClientError:
            return []

"""AWS (SQS) queue adapter."""

from __future__ import annotations

from typing import Any, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import QueuePort


class SQSQueue(QueuePort):
    """QueuePort backed by AWS SQS (or LocalStack-compatible endpoint)."""

    def __init__(self, endpoint_url: Optional[str] = None, region_name: str = "us-east-1") -> None:
        kwargs: dict = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("sqs", **kwargs)
        self._url_cache: dict[str, str] = {}

    def _queue_url(self, queue_name: str) -> str:
        if queue_name not in self._url_cache:
            try:
                resp = self._client.get_queue_url(QueueName=queue_name)
                self._url_cache[queue_name] = resp["QueueUrl"]
            except ClientError:
                resp = self._client.create_queue(QueueName=queue_name)
                self._url_cache[queue_name] = resp["QueueUrl"]
        return self._url_cache[queue_name]

    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        params: dict[str, Any] = {"QueueUrl": self._queue_url(queue_name), "MessageBody": body}
        if attributes:
            params["MessageAttributes"] = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.send_message(**params)
        return resp["MessageId"]

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        resp = self._client.receive_message(
            QueueUrl=self._queue_url(queue_name),
            MaxNumberOfMessages=max_messages,
            WaitTimeSeconds=wait_seconds,
        )
        return [
            {
                "message_id": m["MessageId"],
                "body": m["Body"],
                "receipt_handle": m["ReceiptHandle"],
            }
            for m in resp.get("Messages", [])
        ]

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        self._client.delete_message(QueueUrl=self._queue_url(queue_name), ReceiptHandle=receipt_handle)

"""AWS (SNS) eventing adapter."""

from __future__ import annotations

from typing import Optional

import boto3

from shared.adapters.ports import EventingPort


class SNSEventing(EventingPort):
    """EventingPort backed by AWS SNS (or LocalStack-compatible endpoint)."""

    def __init__(self, endpoint_url: Optional[str] = None, region_name: str = "us-east-1") -> None:
        kwargs: dict = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("sns", **kwargs)
        self._arn_cache: dict[str, str] = {}

    def _topic_arn(self, topic: str) -> str:
        if topic not in self._arn_cache:
            resp = self._client.create_topic(Name=topic)
            self._arn_cache[topic] = resp["TopicArn"]
        return self._arn_cache[topic]

    def publish(self, topic: str, message: str, attributes: Optional[dict[str, str]] = None) -> str:
        params: dict = {"TopicArn": self._topic_arn(topic), "Message": message}
        if attributes:
            params["MessageAttributes"] = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.publish(**params)
        return resp["MessageId"]

    def subscribe(self, topic: str, callback_url_or_id: str) -> str:
        resp = self._client.subscribe(
            TopicArn=self._topic_arn(topic),
            Protocol="https" if callback_url_or_id.startswith("http") else "email",
            Endpoint=callback_url_or_id,
        )
        return resp["SubscriptionArn"]

"""AWS (Secrets Manager) secrets adapter."""

from __future__ import annotations

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import SecretsPort


class SMSecrets(SecretsPort):
    """SecretsPort backed by AWS Secrets Manager (or LocalStack-compatible endpoint)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        kwargs: dict = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("secretsmanager", **kwargs)

    def get_secret(self, secret_id: str) -> str:
        try:
            resp = self._client.get_secret_value(SecretId=secret_id)
            return resp["SecretString"]
        except ClientError as exc:
            if exc.response["Error"]["Code"] == "ResourceNotFoundException":
                raise KeyError(secret_id) from exc
            raise

    def put_secret(self, secret_id: str, value: str) -> None:
        try:
            self._client.create_secret(Name=secret_id, SecretString=value)
        except ClientError as exc:
            if exc.response["Error"]["Code"] == "ResourceAlreadyExistsException":
                self._client.put_secret_value(SecretId=secret_id, SecretString=value)
            else:
                raise

"""AWS (CloudWatch Logs) log sink adapter."""

from __future__ import annotations

import time

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import LogSinkPort


class CloudWatchLogSink(LogSinkPort):
    """LogSinkPort backed by AWS CloudWatch Logs (or LocalStack-compatible endpoint)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        kwargs: dict = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("logs", **kwargs)

    def _ensure_group_and_stream(self, log_group: str, log_stream: str) -> None:
        try:
            self._client.create_log_group(logGroupName=log_group)
        except ClientError:
            pass
        try:
            self._client.create_log_stream(logGroupName=log_group, logStreamName=log_stream)
        except ClientError:
            pass

    def emit(self, log_group: str, log_stream: str, message: str) -> None:
        self._ensure_group_and_stream(log_group, log_stream)
        self._client.put_log_events(
            logGroupName=log_group,
            logStreamName=log_stream,
            logEvents=[{"timestamp": int(time.time() * 1000), "message": message}],
        )

"""On-prem (MinIO) object storage adapter."""

from __future__ import annotations

from typing import Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import ObjectStoragePort


class MinIOObjectStorage(ObjectStoragePort):
    """
    ObjectStoragePort backed by MinIO.

    MinIO is S3-compatible, so we use the same boto3 client with a different
    endpoint.  The adapter is separate to allow on-prem-specific configuration
    (TLS, auth, path-style access) without polluting the AWS adapter.
    """

    def __init__(
        self,
        endpoint_url: str = "http://localhost:9000",
        access_key: str = "minioadmin",
        secret_key: str = "minioadmin",
        region_name: str = "us-east-1",
    ) -> None:
        self._client = boto3.client(
            "s3",
            endpoint_url=endpoint_url,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key,
            region_name=region_name,
        )

    def _ensure_bucket(self, bucket: str) -> None:
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            self._client.create_bucket(Bucket=bucket)

    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[dict[str, str]] = None) -> None:
        self._ensure_bucket(bucket)
        params: dict = {"Bucket": bucket, "Key": key, "Body": data}
        if metadata:
            params["Metadata"] = metadata
        self._client.put_object(**params)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(Bucket=bucket, Key=key)
            return resp["Body"].read()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in ("NoSuchKey", "404"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.delete_object(Bucket=bucket, Key=key)

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        try:
            resp = self._client.list_objects_v2(Bucket=bucket, Prefix=prefix)
            return [obj["Key"] for obj in resp.get("Contents", [])]
        except ClientError:
            return []

"""
AdapterRegistry — profile-aware adapter factory.

Reads DEPLOYMENT_PROFILE from the environment and returns the correct
concrete adapter for each port slot.  Business code never imports concrete
adapters directly; it calls registry accessors that return port-typed objects.

Environment variables consumed:
  DEPLOYMENT_PROFILE  — "aws" | "onprem" (default: "onprem")

AWS-profile env vars (optional, for LocalStack / non-default endpoints):
  AWS_ENDPOINT_URL    — override endpoint for all AWS services
  AWS_REGION          — override region (default: us-east-1)

On-prem-profile env vars (optional):
  MINIO_ENDPOINT_URL  — MinIO endpoint (default: http://localhost:9000)
  MINIO_ACCESS_KEY    — MinIO access key (default: minioadmin)
  MINIO_SECRET_KEY    — MinIO secret key (default: minioadmin)
"""

from __future__ import annotations

import os
from typing import Optional

from shared.adapters.adapter_contract import AdapterContractError, DeploymentProfile
from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)


class AdapterRegistry:
    """
    Central adapter registry.  Instantiate with a profile or let it read
    DEPLOYMENT_PROFILE from the environment.
    """

    def __init__(self, profile: Optional[str] = None) -> None:
        raw = profile or os.environ.get("DEPLOYMENT_PROFILE", "onprem")
        try:
            self._profile = DeploymentProfile(raw.lower())
        except ValueError:
            raise AdapterContractError(
                f"Unknown DEPLOYMENT_PROFILE '{raw}'. "
                f"Supported: {[p.value for p in DeploymentProfile]}"
            ) from None

    @property
    def profile(self) -> DeploymentProfile:
        return self._profile

    # -- AWS helpers -----------------------------------------------------------

    def _aws_endpoint(self) -> Optional[str]:
        return os.environ.get("AWS_ENDPOINT_URL")

    def _aws_region(self) -> str:
        return os.environ.get("AWS_REGION", "us-east-1")

    # -- On-prem helpers -------------------------------------------------------

    def _minio_endpoint(self) -> str:
        return os.environ.get("MINIO_ENDPOINT_URL", "http://localhost:9000")

    def _minio_access_key(self) -> str:
        return os.environ.get("MINIO_ACCESS_KEY", "minioadmin")

    def _minio_secret_key(self) -> str:
        return os.environ.get("MINIO_SECRET_KEY", "minioadmin")

    # -- Adapter accessors (port-typed) ----------------------------------------

    def object_storage(self) -> ObjectStoragePort:
        if self._profile == DeploymentProfile.AWS:
            from shared.adapters.aws.object_storage import S3ObjectStorage
            return S3ObjectStorage(endpoint_url=self._aws_endpoint(), region_name=self._aws_region())
        else:
            from shared.adapters.onprem.object_storage import MinIOObjectStorage
            return MinIOObjectStorage(
                endpoint_url=self._minio_endpoint(),
                access_key=self._minio_access_key(),
                secret_key=self._minio_secret_key(),
            )

    def queue(self) -> QueuePort:
        if self._profile == DeploymentProfile.AWS:
            from shared.adapters.aws.queue import SQSQueue
            return SQSQueue(endpoint_url=self._aws_endpoint(), region_name=self._aws_region())
        else:
            from shared.adapters.onprem.queue import FileSystemQueue
            return FileSystemQueue()

    def eventing(self) -> EventingPort:
        if self._profile == DeploymentProfile.AWS:
            from shared.adapters.aws.eventing import SNSEventing
            return SNSEventing(endpoint_url=self._aws_endpoint(), region_name=self._aws_region())
        else:
            from shared.adapters.onprem.eventing import InProcessEventing
            return InProcessEventing()

    def secrets(self) -> SecretsPort:
        if self._profile == DeploymentProfile.AWS:
            from shared.adapters.aws.secrets import SMSecrets
            return SMSecrets(endpoint_url=self._aws_endpoint(), region_name=self._aws_region())
        else:
            from shared.adapters.onprem.secrets import EnvFileSecrets
            return EnvFileSecrets()

    def log_sink(self) -> LogSinkPort:
        if self._profile == DeploymentProfile.AWS:
            from shared.adapters.aws.log_sink import CloudWatchLogSink
            return CloudWatchLogSink(endpoint_url=self._aws_endpoint(), region_name=self._aws_region())
        else:
            from shared.adapters.onprem.log_sink import StdoutJsonLogSink
            return StdoutJsonLogSink()


# Module-level convenience — singleton per process (lazy).
_default_registry: Optional[AdapterRegistry] = None


def get_registry() -> AdapterRegistry:
    """Return (and cache) the default registry based on DEPLOYMENT_PROFILE."""
    global _default_registry  # noqa: PLW0603
    if _default_registry is None:
        _default_registry = AdapterRegistry()
    return _default_registry


def reset_registry() -> None:
    """Reset the cached default registry.  Useful in tests."""
    global _default_registry  # noqa: PLW0603
    _default_registry = None

