"""
Adapter contract validation and profile constants.

This module defines:
  - The canonical set of DEPLOYMENT_PROFILE values.
  - The canonical set of adapter slot names.
  - A validation helper that asserts a registry satisfies all port contracts.

No business-logic forks by provider live here — only parity/validation rules.
"""

from __future__ import annotations

from enum import Enum
from typing import TYPE_CHECKING

from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)

if TYPE_CHECKING:
    from shared.adapters.registry import AdapterRegistry


class DeploymentProfile(str, Enum):
    """Supported deployment profiles."""

    AWS = "aws"
    ONPREM = "onprem"


# Canonical adapter slot names and their expected port types.
ADAPTER_SLOTS: dict[str, type] = {
    "object_storage": ObjectStoragePort,
    "queue": QueuePort,
    "eventing": EventingPort,
    "secrets": SecretsPort,
    "log_sink": LogSinkPort,
}


class AdapterContractError(Exception):
    """Raised when a registry does not satisfy the adapter contract."""


def validate_registry(registry: "AdapterRegistry") -> None:
    """
    Assert that *registry* exposes every canonical adapter slot and that each
    returned adapter is an instance of the corresponding port type.

    Raises AdapterContractError with a summary of all violations.
    """
    violations: list[str] = []
    for slot_name, port_type in ADAPTER_SLOTS.items():
        accessor = getattr(registry, slot_name, None)
        if accessor is None:
            violations.append(f"Registry missing accessor '{slot_name}'")
            continue
        try:
            instance = accessor()
        except Exception as exc:  # noqa: BLE001
            violations.append(f"Accessor '{slot_name}' raised {type(exc).__name__}: {exc}")
            continue
        if not isinstance(instance, port_type):
            violations.append(
                f"Accessor '{slot_name}' returned {type(instance).__name__}, "
                f"expected {port_type.__name__}"
            )
    if violations:
        raise AdapterContractError(
            f"{len(violations)} contract violation(s):\n" + "\n".join(f"  - {v}" for v in violations)
        )

