"""On-prem queue adapter backed by a simple filesystem-based queue.

For production on-prem deployments this would be backed by RabbitMQ, Redis
Streams, or similar.  This implementation provides a filesystem-based queue
that satisfies the QueuePort contract without requiring external services
beyond what is available in a minimal on-prem environment.

The adapter is intentionally simple and deterministic for local-dev and
integration testing.  A production on-prem deployment would swap this for
a RabbitMQ or Redis adapter with the same QueuePort interface.
"""

from __future__ import annotations

import json
import os
import tempfile
import uuid
from typing import Any, Optional

from shared.adapters.ports import QueuePort


class FileSystemQueue(QueuePort):
    """QueuePort backed by local filesystem directories."""

    def __init__(self, base_dir: str | None = None) -> None:
        self._base_dir = base_dir or os.path.join(tempfile.gettempdir(), "onprem_queue")
        os.makedirs(self._base_dir, exist_ok=True)

    def _queue_dir(self, queue_name: str) -> str:
        d = os.path.join(self._base_dir, queue_name)
        os.makedirs(d, exist_ok=True)
        return d

    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        msg_id = uuid.uuid4().hex
        payload = {"message_id": msg_id, "body": body, "attributes": attributes or {}}
        path = os.path.join(self._queue_dir(queue_name), f"{msg_id}.json")
        with open(path, "w") as f:
            json.dump(payload, f)
        return msg_id

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        d = self._queue_dir(queue_name)
        files = sorted(os.listdir(d))[:max_messages]
        results: list[dict[str, Any]] = []
        for fname in files:
            path = os.path.join(d, fname)
            with open(path) as f:
                payload = json.load(f)
            results.append(
                {
                    "message_id": payload["message_id"],
                    "body": payload["body"],
                    "receipt_handle": path,
                }
            )
        return results

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        if os.path.exists(receipt_handle):
            os.remove(receipt_handle)

