"""On-prem secrets adapter — environment-variable / file-based.

For production on-prem this would be HashiCorp Vault or similar.
"""

from __future__ import annotations

import json
import os
import tempfile

from shared.adapters.ports import SecretsPort


class EnvFileSecrets(SecretsPort):
    """SecretsPort backed by a JSON file on disk (or env vars as fallback)."""

    def __init__(self, secrets_file: str | None = None) -> None:
        self._secrets_file = secrets_file or os.path.join(tempfile.gettempdir(), "onprem_secrets.json")
        if not os.path.exists(self._secrets_file):
            with open(self._secrets_file, "w") as f:
                json.dump({}, f)

    def _load(self) -> dict[str, str]:
        with open(self._secrets_file) as f:
            return json.load(f)

    def _save(self, data: dict[str, str]) -> None:
        with open(self._secrets_file, "w") as f:
            json.dump(data, f)

    def get_secret(self, secret_id: str) -> str:
        # Try env var first, then file.
        env_val = os.environ.get(secret_id)
        if env_val is not None:
            return env_val
        data = self._load()
        if secret_id not in data:
            raise KeyError(secret_id)
        return data[secret_id]

    def put_secret(self, secret_id: str, value: str) -> None:
        data = self._load()
        data[secret_id] = value
        self._save(data)

