SRC_DIR = os.path.join(os.path.dirname(__file__), "..", "..", "src")
if SRC_DIR not in sys.path:
    sys.path.insert(0, SRC_DIR)

from shared.adapters import (  # noqa: E402
    AdapterRegistry,
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
