class TestDeploymentProfile:
    """Profile enum and env-var selection."""

    def test_aws_profile_value(self) -> None:
        assert DeploymentProfile.AWS.value == "aws"

    def test_onprem_profile_value(self) -> None:
        assert DeploymentProfile.ONPREM.value == "onprem"

    def test_invalid_profile_raises(self) -> None:
        with pytest.raises(AdapterContractError, match="Unknown DEPLOYMENT_PROFILE"):
            AdapterRegistry(profile="invalid_xyz")

    def test_profile_case_insensitive(self) -> None:
        reg = AdapterRegistry(profile="AWS")
        assert reg.profile == DeploymentProfile.AWS

        reg2 = AdapterRegistry(profile="OnPrem")
        assert reg2.profile == DeploymentProfile.ONPREM


class TestRegistryProfileSelection:
    """Registry returns correct adapter types per profile."""

    def test_onprem_registry_returns_port_instances(self) -> None:
        reg = AdapterRegistry(profile="onprem")
        assert isinstance(reg.object_storage(), ObjectStoragePort)
        assert isinstance(reg.queue(), QueuePort)
        assert isinstance(reg.eventing(), EventingPort)
        assert isinstance(reg.secrets(), SecretsPort)
        assert isinstance(reg.log_sink(), LogSinkPort)

    def test_aws_registry_returns_port_instances(self) -> None:
        """AWS adapters are instantiable (boto3 client creation does not need live AWS)."""
        reg = AdapterRegistry(profile="aws")
        assert isinstance(reg.object_storage(), ObjectStoragePort)
        assert isinstance(reg.queue(), QueuePort)
        assert isinstance(reg.eventing(), EventingPort)
        assert isinstance(reg.secrets(), SecretsPort)
        assert isinstance(reg.log_sink(), LogSinkPort)

    def test_env_var_selection(self, monkeypatch: pytest.MonkeyPatch) -> None:
        reset_registry()
        monkeypatch.setenv("DEPLOYMENT_PROFILE", "onprem")
        reg = get_registry()
        assert reg.profile == DeploymentProfile.ONPREM
        reset_registry()

