        monkeypatch.setenv("DEPLOYMENT_PROFILE", "onprem")
        reg_onprem = get_registry()
        storage_onprem = reg_onprem.object_storage()

        reset_registry()
        monkeypatch.setenv("DEPLOYMENT_PROFILE", "aws")
